#!/usr/bin/env node
/**
 * Builds the General template's fixture (RT-2b).
 *
 * One small repository with a main branch and a feature branch. The feature
 * branch breaks each of the template's twelve rules once, and beside each
 * plant makes a change of the same shape that is right, with the test that
 * proves it. A template that reads well and finds nothing misses the plants;
 * one that fires on correct code fails the look-alikes.
 *
 * The key is derived, as the seeded fixture's is: each plant's line is found
 * by its marker text in the file as built, never counted by hand.
 *
 * The plants carry no tests of their own, so a finding under rule 8 in a
 * planted file is the rule working. A run is scored by file and line, not by
 * the rule cited.
 */

import { execFileSync } from "node:child_process";
